-- Esports Hub v3 core (ADR-1 option A: everything on D1). GENERATED by drizzle-kit from src/v3/db/schema.ts (scripts/v3-migration.mjs), then made
-- idempotent. Additive only: 14 new tables, no legacy table is changed here (the three users columns are in 0052). Every v3 route is behind a flag that is
-- OFF by default and answers 404 before touching these tables, so a Worker can be deployed before this file is applied.
-- Rollback is "empty, do not drop".
CREATE TABLE IF NOT EXISTS `discord_guilds` (
	`guild_id` text PRIMARY KEY NOT NULL,
	`installed_by_user_id` text,
	`permissions_ok` integer DEFAULT false NOT NULL,
	`installed_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`installed_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE TABLE IF NOT EXISTS `discord_outbox` (
	`id` text PRIMARY KEY NOT NULL,
	`kind` text NOT NULL,
	`guild_id` text NOT NULL,
	`payload` text DEFAULT '{}' NOT NULL,
	`idempotency_key` text NOT NULL,
	`status` text DEFAULT 'pending' NOT NULL,
	`attempts` integer DEFAULT 0 NOT NULL,
	`run_after` integer DEFAULT (unixepoch()) NOT NULL,
	`last_error` text,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	CONSTRAINT "discord_outbox_kind_ck" CHECK(kind IN ('create_team_channel','assign_team_role','ping_lobby','post_result','archive_channels')),
	CONSTRAINT "discord_outbox_status_ck" CHECK(status IN ('pending','running','done','failed','dead'))
);

CREATE UNIQUE INDEX IF NOT EXISTS `discord_outbox_key_uq` ON `discord_outbox` (`idempotency_key`);
CREATE INDEX IF NOT EXISTS `discord_outbox_due_idx` ON `discord_outbox` (`status`,`run_after`);
CREATE TABLE IF NOT EXISTS `dispute_events` (
	`id` text PRIMARY KEY NOT NULL,
	`dispute_id` text NOT NULL,
	`actor_user_id` text,
	`actor_role` text NOT NULL,
	`action` text NOT NULL,
	`from_status` text,
	`to_status` text,
	`note` text,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`dispute_id`) REFERENCES `disputes`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`actor_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE INDEX IF NOT EXISTS `dispute_events_dispute_idx` ON `dispute_events` (`dispute_id`,`created_at`);
CREATE TABLE IF NOT EXISTS `dispute_evidence` (
	`id` text PRIMARY KEY NOT NULL,
	`dispute_id` text NOT NULL,
	`uploaded_by_user_id` text,
	`mime_type` text NOT NULL,
	`size_bytes` integer NOT NULL,
	`sha256` text NOT NULL,
	`caption` text,
	`purge_after` integer,
	`purged_at` integer,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`dispute_id`) REFERENCES `disputes`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`uploaded_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "dispute_evidence_mime_ck" CHECK(mime_type IN ('image/png','image/jpeg','image/webp')),
	CONSTRAINT "dispute_evidence_size_ck" CHECK(size_bytes > 0 AND size_bytes <= 409600)
);

CREATE INDEX IF NOT EXISTS `dispute_evidence_dispute_idx` ON `dispute_evidence` (`dispute_id`);
CREATE INDEX IF NOT EXISTS `dispute_evidence_purge_idx` ON `dispute_evidence` (`purge_after`);
CREATE UNIQUE INDEX IF NOT EXISTS `dispute_evidence_hash_uq` ON `dispute_evidence` (`dispute_id`,`sha256`);
CREATE TABLE IF NOT EXISTS `dispute_evidence_blobs` (
	`evidence_id` text PRIMARY KEY NOT NULL,
	`bytes` blob NOT NULL,
	FOREIGN KEY (`evidence_id`) REFERENCES `dispute_evidence`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE TABLE IF NOT EXISTS `disputes` (
	`id` text PRIMARY KEY NOT NULL,
	`tournament_id` text NOT NULL,
	`match_id` text,
	`match_no` integer,
	`type` text NOT NULL,
	`status` text DEFAULT 'open' NOT NULL,
	`raised_by_user_id` text,
	`raised_by_team` text,
	`raised_by_team_key` text,
	`against_team` text,
	`against_team_key` text,
	`summary` text NOT NULL,
	`outcome` text,
	`resolution_note` text,
	`resolved_by_user_id` text,
	`resolved_at` integer,
	`due_at` integer NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`tournament_id`) REFERENCES `tournaments`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`raised_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	FOREIGN KEY (`resolved_by_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null,
	CONSTRAINT "disputes_type_ck" CHECK(type IN ('tie_breaker','wrong_score','cheating_claim','no_show','roster_violation','other')),
	CONSTRAINT "disputes_status_ck" CHECK(status IN ('open','evidence_requested','under_review','resolved','rejected','escalated','withdrawn')),
	CONSTRAINT "disputes_outcome_ck" CHECK(outcome IS NULL OR outcome IN ('upheld','partially_upheld','rejected','no_action')),
	CONSTRAINT "disputes_resolved_ck" CHECK((status IN ('resolved','rejected')) = (resolved_at IS NOT NULL)),
	CONSTRAINT "disputes_summary_len_ck" CHECK(length(summary) <= 1000)
);

CREATE INDEX IF NOT EXISTS `disputes_queue_idx` ON `disputes` (`tournament_id`,`status`,`due_at`);
CREATE INDEX IF NOT EXISTS `disputes_raised_by_idx` ON `disputes` (`raised_by_user_id`);
CREATE TABLE IF NOT EXISTS `lft_applications` (
	`id` text PRIMARY KEY NOT NULL,
	`listing_id` text NOT NULL,
	`applicant_user_id` text NOT NULL,
	`message` text,
	`contact` text,
	`status` text DEFAULT 'sent' NOT NULL,
	`responded_at` integer,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`listing_id`) REFERENCES `lft_listings`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`applicant_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "lft_applications_status_ck" CHECK(status IN ('sent','accepted','declined','withdrawn'))
);

CREATE UNIQUE INDEX IF NOT EXISTS `lft_applications_once_uq` ON `lft_applications` (`listing_id`,`applicant_user_id`);
CREATE INDEX IF NOT EXISTS `lft_applications_applicant_idx` ON `lft_applications` (`applicant_user_id`);
CREATE TABLE IF NOT EXISTS `lft_listings` (
	`id` text PRIMARY KEY NOT NULL,
	`kind` text NOT NULL,
	`author_user_id` text NOT NULL,
	`team_profile_id` text,
	`game` text NOT NULL,
	`roles` text DEFAULT '[]' NOT NULL,
	`rank_min_ordinal` integer,
	`rank_max_ordinal` integer,
	`state` text,
	`city` text,
	`online_ok` integer DEFAULT true NOT NULL,
	`message` text NOT NULL,
	`contact` text,
	`status` text DEFAULT 'open' NOT NULL,
	`hidden_at` integer,
	`expires_at` integer NOT NULL,
	`last_bumped_at` integer DEFAULT (unixepoch()) NOT NULL,
	`report_count` integer DEFAULT 0 NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`author_user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`team_profile_id`) REFERENCES `team_profiles`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "lft_kind_ck" CHECK(kind IN ('looking_for_team','looking_for_player')),
	CONSTRAINT "lft_status_ck" CHECK(status IN ('open','filled','closed','expired','removed')),
	CONSTRAINT "lft_team_kind_ck" CHECK((kind = 'looking_for_player') = (team_profile_id IS NOT NULL)),
	CONSTRAINT "lft_rank_range_ck" CHECK(rank_min_ordinal IS NULL OR rank_max_ordinal IS NULL OR rank_max_ordinal >= rank_min_ordinal),
	CONSTRAINT "lft_message_len_ck" CHECK(length(message) <= 600)
);

CREATE INDEX IF NOT EXISTS `lft_board_idx` ON `lft_listings` (`status`,`game`,`kind`,`last_bumped_at`);
CREATE INDEX IF NOT EXISTS `lft_author_idx` ON `lft_listings` (`author_user_id`,`status`);
CREATE INDEX IF NOT EXISTS `lft_location_idx` ON `lft_listings` (`game`,`state`,`city`);
CREATE INDEX IF NOT EXISTS `lft_expiry_idx` ON `lft_listings` (`status`,`expires_at`);
CREATE TABLE IF NOT EXISTS `lft_reports` (
	`id` text PRIMARY KEY NOT NULL,
	`listing_id` text NOT NULL,
	`reporter` text NOT NULL,
	`reason_code` text NOT NULL,
	`note` text DEFAULT '' NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`listing_id`) REFERENCES `lft_listings`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "lft_reports_note_ck" CHECK(length(note) <= 200)
);

CREATE UNIQUE INDEX IF NOT EXISTS `lft_reports_once_uq` ON `lft_reports` (`listing_id`,`reporter`);
CREATE TABLE IF NOT EXISTS `player_games` (
	`user_id` text NOT NULL,
	`game` text NOT NULL,
	`in_game_name` text NOT NULL,
	`rank_code` text,
	`rank_ordinal` integer,
	`roles` text DEFAULT '[]' NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "player_games_game_ck" CHECK(game IN ('bgmi','free_fire','valorant','cod_mobile','cs2','other'))
);

CREATE UNIQUE INDEX IF NOT EXISTS `player_games_pk` ON `player_games` (`user_id`,`game`);
CREATE INDEX IF NOT EXISTS `player_games_filter_idx` ON `player_games` (`game`,`rank_ordinal`);
CREATE TABLE IF NOT EXISTS `player_profiles` (
	`user_id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`handle` text NOT NULL,
	`bio` text,
	`city` text,
	`state` text,
	`languages` text DEFAULT '[]' NOT NULL,
	`visibility` text DEFAULT 'private' NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "player_profiles_visibility_ck" CHECK(visibility IN ('private','unlisted','public'))
);

CREATE UNIQUE INDEX IF NOT EXISTS `player_profiles_slug_uq` ON `player_profiles` (`slug`);
CREATE INDEX IF NOT EXISTS `player_profiles_visibility_idx` ON `player_profiles` (`visibility`);
CREATE TABLE IF NOT EXISTS `tournaments` (
	`id` text PRIMARY KEY NOT NULL,
	`event_id` text NOT NULL,
	`slug` text NOT NULL,
	`title` text NOT NULL,
	`game` text NOT NULL,
	`format` text NOT NULL,
	`status` text DEFAULT 'draft' NOT NULL,
	`venue` text DEFAULT 'online' NOT NULL,
	`city` text,
	`state` text,
	`summary` text,
	`description` text,
	`rules` text,
	`max_teams` integer,
	`starts_at` integer,
	`ends_at` integer,
	`seo_ready` integer DEFAULT false NOT NULL,
	`published_at` integer,
	`discord_guild_id` text,
	`discord_category_id` text,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	`updated_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `events`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "tournaments_status_ck" CHECK(status IN ('draft','published','registration_open','registration_closed','live','completed','cancelled')),
	CONSTRAINT "tournaments_game_ck" CHECK(game IN ('bgmi','free_fire','valorant','cod_mobile','cs2','other')),
	CONSTRAINT "tournaments_format_ck" CHECK(format IN ('battle_royale_points','single_elimination','double_elimination','round_robin','swiss')),
	CONSTRAINT "tournaments_venue_ck" CHECK(venue IN ('online','offline','hybrid')),
	CONSTRAINT "tournaments_dates_ck" CHECK(starts_at IS NULL OR ends_at IS NULL OR ends_at >= starts_at)
);

CREATE UNIQUE INDEX IF NOT EXISTS `tournaments_event_id_unique` ON `tournaments` (`event_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `tournaments_slug_uq` ON `tournaments` (`slug`);
CREATE INDEX IF NOT EXISTS `tournaments_status_start_idx` ON `tournaments` (`status`,`starts_at`);
CREATE INDEX IF NOT EXISTS `tournaments_game_idx` ON `tournaments` (`game`,`starts_at`);
CREATE TABLE IF NOT EXISTS `v3_result_corrections` (
	`id` text PRIMARY KEY NOT NULL,
	`dispute_id` text NOT NULL,
	`event_id` text NOT NULL,
	`match_ref` text NOT NULL,
	`old_value` text NOT NULL,
	`new_value` text NOT NULL,
	`applied_by` text,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`dispute_id`) REFERENCES `disputes`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`event_id`) REFERENCES `events`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`applied_by`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE set null
);

CREATE INDEX IF NOT EXISTS `v3_result_corrections_event_idx` ON `v3_result_corrections` (`event_id`,`match_ref`);
CREATE INDEX IF NOT EXISTS `v3_result_corrections_dispute_idx` ON `v3_result_corrections` (`dispute_id`);
CREATE TABLE IF NOT EXISTS `v3_team_captains` (
	`event_id` text NOT NULL,
	`team_key` text NOT NULL,
	`team_name` text NOT NULL,
	`user_id` text NOT NULL,
	`created_at` integer DEFAULT (unixepoch()) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `events`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);

CREATE UNIQUE INDEX IF NOT EXISTS `v3_team_captains_pk` ON `v3_team_captains` (`event_id`,`team_key`,`user_id`);
CREATE INDEX IF NOT EXISTS `v3_team_captains_user_idx` ON `v3_team_captains` (`user_id`);

-- Append-only dispute history. Exactly two changes are allowed, both for account deletion: actor_user_id to NULL, and note to '[deleted]'.
CREATE TRIGGER IF NOT EXISTS trg_dispute_events_append_only BEFORE UPDATE ON dispute_events
WHEN NEW.id IS NOT OLD.id OR NEW.dispute_id IS NOT OLD.dispute_id OR NEW.actor_role IS NOT OLD.actor_role OR NEW.action IS NOT OLD.action
  OR NEW.from_status IS NOT OLD.from_status OR NEW.to_status IS NOT OLD.to_status OR NEW.created_at IS NOT OLD.created_at
  OR (NEW.note IS NOT OLD.note AND NEW.note IS NOT '[deleted]')
BEGIN SELECT RAISE(ABORT, 'dispute_events is append-only'); END;
